const rows = $input.all().map(i => i.json);
const today = new Date();
const dayStart = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())).getTime();
const MS = 86400000;
function dayDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(String(dateStr).slice(0,10) + 'T00:00:00Z').getTime();
  return Math.round((d - dayStart) / MS);
}
const due = [];
for (const r of rows) {
  if (String(r.status || '') !== 'confirmed') continue;
  const s = dayDiff(r.start_date);
  const e = dayDiff(r.end_date);
  let action = 'none';
  if (s === 1) action = 'pickup';
  else if (e === 0) action = 'return';
  else if (e !== null && e < 0) action = 'late';
  if (action === 'none') continue;
  due.push({
    booking_id: String(r.booking_id || ''),
    renter_name: String(r.renter_name || ''),
    renter_email: String(r.renter_email || ''),
    items: String(r.items || ''),
    start_date: String(r.start_date || ''),
    end_date: String(r.end_date || ''),
    action: action,
  });
}
return [{ json: { due: due, due_count: due.length } }];

const items = $input.all().map(i => i.json);
const out = [];
for (const r of items) {
  const action = String(r.action || '');
  let subject = 'Your rental confirmation';
  let body = '';
  if (action === 'pickup') {
    subject = 'Your rental pickup is tomorrow';
    body = 'Hi ' + (r.renter_name || 'there') + ',

This is a reminder that your rental pickup is scheduled for tomorrow, ' + (r.start_date || '') + '. Items: ' + (r.items || '') + '.

Our team will have everything ready at the agreed time. Please bring a valid ID.

Thanks,
Rental Team';
  } else if (action === 'return') {
    subject = 'Please return your rental today';
    body = 'Hi ' + (r.renter_name || 'there') + ',

Your rental is due back today, ' + (r.end_date || '') + '. Items: ' + (r.items || '') + '.

Please return everything to our location before closing time.

Thanks,
Rental Team';
  } else if (action === 'late') {
    subject = 'Your rental items are overdue';
    body = 'Hi ' + (r.renter_name || 'there') + ',

It looks like your rental items are overdue. They were due back on ' + (r.end_date || '') + '. Please arrange to return them as soon as possible to avoid late fees.

Thanks,
Rental Team';
  }
  out.push({ json: { to: r.renter_email || '', subject: subject, body: body, booking_id: r.booking_id || '', action: action } });
}
return out;

const items = $input.all().map(i => i.json);
let pickups = 0, returns = 0, late = 0;
for (const r of items) {
  if (r.action === 'pickup') pickups++;
  else if (r.action === 'return') returns++;
  else if (r.action === 'late') late++;
}
return [{ json: { reminder_count: items.length, pickups: pickups, returns: returns, late: late,
  summary: pickups + ' pickup reminders, ' + returns + ' return reminders, ' + late + ' late notices' } }];

const inp = $('Normalize Booking Request').item.json;
const agentOut = $input.first().json;
let out = {};
try {
  out = JSON.parse(String(agentOut.output || '{}').replace(/```json\s*/g, '').replace(/```/g, ''));
} catch (e) { out = {}; }
const availability = String(out.availability || 'conflict');
return [{ json: {
  booking_id: inp.booking_id || '',
  renter_name: inp.renter_name || '',
  renter_email: inp.renter_email || '',
  items: inp.items || '',
  start_date: inp.start_date || '',
  end_date: inp.end_date || '',
  total_qty: inp.total_qty || 0,
  created_at: inp.created_at || '',
  availability: availability,
  status: availability === 'available' ? 'confirmed' : 'conflict',
  message: String(out.message || 'We will review your rental request and get back to you.'),
  summary: String(out.summary || 'Booking request received.'),
} }];

