const ret = $('Normalize Return').item.json;
const rows = $input.all().map(i => i.json);
const wanted = String(ret.item_name || '').trim().toLowerCase();
let match = null;
for (const r of rows) {
  if (String(r.item_name || '').trim().toLowerCase() === wanted) { match = r; break; }
}
if (match) {
  const booked = Number(match.booked_qty || 0);
  const condition = String(ret.condition || 'good');
  return [{ json: {
    return_id: ret.return_id || '',
    booking_id: ret.booking_id || '',
    renter_email: ret.renter_email || '',
    item_name: String(match.item_name || ''),
    returned_date: ret.returned_date || '',
    notes: String(ret.notes || ''),
    condition: condition,
    deposit_note: (condition !== 'good' && condition !== '') ? ('Deposit review needed for ' + match.item_name + ' (' + condition + ')') : '',
    damage_alert: (condition === 'damaged' || condition === 'missing'),
    booked_qty: booked,
    new_booked_qty: Math.max(0, booked - 1),
    found: true,
  } }];
}
return [{ json: {
  return_id: ret.return_id || '',
  booking_id: ret.booking_id || '',
  renter_email: ret.renter_email || '',
  item_name: ret.item_name || '',
  returned_date: ret.returned_date || '',
  notes: ret.notes || '',
  condition: String(ret.condition || ''),
  found: false,
} }];

const bookings = $('Read Bookings for Digest').all().map(i => i.json);
const returns = $('Read Returns for Digest').all().map(i => i.json);
const today = new Date();
const dayStart = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate())).getTime();
const MS = 86400000;
function dayDiff(dateStr) {
  if (!dateStr) return null;
  const d = new Date(String(dateStr).slice(0,10) + 'T00:00:00Z').getTime();
  return Math.round((d - dayStart) / MS);
}
const active = bookings.filter(r => String(r.status || '') === 'confirmed');
const conflicts = bookings.filter(r => String(r.status || '') === 'conflict');
const late = active.filter(r => { const e = dayDiff(r.end_date); return e !== null && e < 0; });
const upcoming = active.filter(r => { const s = dayDiff(r.start_date); return s !== null && s >= 0 && s <= 7; });
const itemCounts = {};
for (const b of bookings) {
  const parts = String(b.items || '').split(',').map(s => s.trim()).filter(Boolean);
  for (const p of parts) { itemCounts[p] = (itemCounts[p] || 0) + 1; }
}
const topItems = Object.entries(itemCounts).sort((a, b) => b[1] - a[1]).slice(0, 3).map(e => e[0] + ' x' + e[1]).join(', ') || 'none';
return [{ json: {
  total_bookings: bookings.length,
  active_count: active.length,
  conflict_count: conflicts.length,
  returned_count: returns.length,
  late_count: late.length,
  upcoming_count: upcoming.length,
  top_items: topItems,
  digest_date: new Date().toISOString().slice(0, 10),
} }];

const inp = $input.first().json;
const stats = $('Compute Digest Stats').item.json;
let digest = String(inp.output || '');
digest = digest.replace(/```\w*\s*/g, '').trim();
return [{ json: Object.assign({}, stats, { digest: digest }) }];
